    assert_no_record_zero_assign(run);
    assert!(
        run.blocks
            .iter()
            .flat_map(|b| &b.stmts)
            .any(|s| matches!(s, ir::Stmt::RecordInit(_, ir::RecordId(0)))),
        "record-return temp is default-initialized with RecordInit:\n{run}"
    );
