/// Signedness follows the terminal record leaf through a component field path.
/// Otherwise `sint<8> >> 1` silently becomes a logical right shift in TBIR C++.
#[test]
fn component_record_signed_leaf_uses_arithmetic_right_shift() {
    let src = r#"
struct SignedSample
    bias : sint<8> default 0
end struct SignedSample

transactor ShiftSource
    observed : out event<sint<8>>
    current  : SignedSample
    shifted  : sint<8> default 0
    when active
        on 1 cycles
            current.bias = -8
            shifted = current.bias >> 1
        end on
    end when
end transactor ShiftSource

test T
    let dut : Top
    let src : ShiftSource active
    run
        wait 2 cycles
        assert src.shifted == -4 else fail("signed shift")
    end run
end test T
"#;

    let cpp = emit_cpp_src(src);
    assert!(
        cpp.contains("((int64_t)(self.current.bias)) >> 1"),
        "signed record leaf must get an arithmetic shift:\n{cpp}"
    );
}

/// Non-periodic cycle-trigger bodies own the same self-relative component
/// state as methods and periodic handlers. Signedness must therefore resolve
/// through the cycle-handler function id as well.
#[test]
fn component_record_signed_leaf_in_cycle_trigger_uses_arithmetic_right_shift() {
    let src = r#"
struct SignedSample
    bias : sint<8> default -8
end struct SignedSample

transactor ShiftSource
    observed : out event<sint<8>>
    current  : SignedSample
    shifted  : sint<8> default 0
    when active
        on current.bias < 0
            shifted = current.bias >> 1
        end on
    end when
end transactor ShiftSource

test T
    let dut : Top
    let src : ShiftSource active
    run
        wait 2 cycles
        assert src.shifted == -4 else fail("signed shift lost")
    end run
end test T
"#;

    let cpp = emit_cpp_src(src);
    assert!(
        cpp.contains("((int64_t)(self.current.bias)) >> 1"),
        "signed record leaf must get an arithmetic shift in a cycle handler:\n{cpp}"
    );
}

/// Every whole-`Vec` diagnostic must recommend a spelling that
/// actually lowers. The suggestion is "index the field element-wise
/// (`X[i]`)", so the test follows its own advice and checks the
/// indexed form gets through — in the component lane, where the
/// suggestion was added and the indexed form did NOT lower until the
/// element-access node was wired up.
///
/// This is the guard, not a restatement of it: with the element lane
/// removed, the whole-`Vec` read still refuses and still says
/// "element-wise", and the indexed follow-up fails — which is the
/// dead-end loop this exists to forbid.
#[test]
fn component_record_vec_diagnostic_does_not_promise_an_unsupported_workaround() {
    let prog = |body: &str| {
        format!(
            r#"
struct Inner
    bytes : Vec<uint<8>, 2>
end struct Inner
struct Outer
    inner : Inner
end struct Outer

transactor VecSource
    observed : out event<uint<8>>
    current  : Outer
    when active
        hookable touch()
            {body}
        end touch
    end when
end transactor VecSource

test T
    let dut : Top
    let src : VecSource active
    run
        src.touch()
    end run
end test T
"#
        )
    };

    // A landing that is still refused, and whose message carries the
    // suggestion.
    let err = lower_src(&prog("let z = current.inner.bytes")).expect_err("whole-`Vec` read");
    let msg = assert_not_implemented(&err, lower::V1Status::EmitsUncompilable);
    assert!(
        msg.contains("element-wise"),
        "carries the suggestion: {msg}"
    );
    // The suggestion names the path the USER wrote, not the record
    // type it resolved to and not the emission suffix.
    assert!(
        msg.contains("`current.inner.bytes[i]`"),
        "names the user's own path: {msg}"
    );

    // …and following it lowers, under both backends.
    for ok in [
        "let z = current.inner.bytes[0]",
        "current.inner.bytes[0] = 1",
        "current.inner.bytes = current.inner.bytes",
    ] {
        let src = prog(ok);
        lower_src(&src).unwrap_or_else(|e| panic!("`{ok}` lowers: {e}"));
        cpp_tb::emit(&merged_src(&src)).unwrap_or_else(|e| panic!("`{ok}`: v1 emits: {e:?}"));
    }
}

/// Hook-triggered covergroups obey the same `hookable` provenance rule as
/// test-scope pre/post handlers; a plain transactor function must not acquire
/// an implicit coverage subscription merely because it shares the method IR.
#[test]
fn a_plain_transactor_function_is_not_a_covergroup_hook_target() {
    let src = r#"covergroup C @(drv.plain(n) post)
    cp : cover dut.count_out
        bins
            zero = {0}
        end bins
end covergroup C

transactor Drv
    dut : Top
    when active
        function plain(n: uint<8>)
            log(info, "plain ${n}")
        end function plain
    end when
end transactor Drv

testbench Tb
    dut : Top
    drv : Drv active
    cov : C
end testbench Tb

impl T for Tb
    run
        drv.dut = dut
        drv.plain(1)
    end run
end impl T"#;

    let v1 = cpp_tb::emit(&merged_src(src)).expect_err("v1 refuses a cover hook on `function`");
    assert!(
        format!("{v1}").contains("must resolve to a `hookable`"),
        "v1 establishes the language contract: {v1}"
    );

    let err = lower_src(src).expect_err("TB-IR must refuse a cover hook on `function`");
    assert!(
        assert_invalid(&err).contains("does not name a `hookable`"),
        "the diagnostic must distinguish a plain function from a hookable: {err}"
    );
}

#[test]
fn component_fixed_vec_elements_lower_emit_and_remain_per_instance() {
    let src = r#"scoreboard Table
    words : Vec<uint<64>, 4>
    shadow : Vec<uint<64>, 4>
    flags : Vec<bool, 4>

    hookable store(index: uint<32>, value: uint<64>)
        words[index] = value
        flags[index] = true
    end store

    hookable snapshot()
        shadow = words
        assert shadow == words else fail("snapshot mismatch")
    end snapshot
end scoreboard Table

testbench Tb
    dut : Top
    a : Table
    b : Table
end testbench Tb

impl T for Tb
    run
        a.store(2, 0x1234)
        b.store(2, 0x5678)
        a.snapshot()
        assert a.flags[2] else fail("a flag")
        assert a.words[2] == 0x1234 else fail("a value")
        assert b.words[2] == 0x5678 else fail("b value")
        assert a.words != b.words else fail("vectors unexpectedly equal")
        a.words = b.words
        assert a.words == b.words else fail("whole-vector copy failed")
        wait 1 cycle
    end run
end impl T"#;

    let prog = lower_src(src).expect("direct component Vec lowers");
    let table = prog.components.iter().find(|c| c.name == "Table").unwrap();
    assert!(matches!(
        &table.field("words").unwrap().kind,
        ir::ComponentFieldKind::FixedVec(v)
            if v.elem == ir::IrType::UInt(Some(64)) && v.len == 4
    ));
    verify::verify_program(&prog).expect("component Vec IR verifies");
    let cpp = emit_cpp_src(src);
    assert!(cpp.contains("std::array<uint64_t, 4> words{};"), "{cpp}");
    assert!(cpp.contains("std::array<bool, 4> flags{};"), "{cpp}");
    assert!(cpp.contains("self.words[index] = value;"), "{cpp}");
    assert!(cpp.contains("self.shadow = self.words;"), "{cpp}");
    assert!(cpp.contains("self.shadow == self.words"), "{cpp}");
    assert!(cpp.contains("a.words = b.words;"), "{cpp}");
    assert!(cpp.contains("a.words == b.words"), "{cpp}");
    assert!(cpp.contains("a.words[2]"), "{cpp}");
    assert!(cpp.contains("b.words[2]"), "{cpp}");
}

#[test]
fn component_fixed_vec_literal_bounds_and_defaults_are_precise() {
    let base = r#"scoreboard Table
    words : Vec<uint<8>, 2>
    hookable keep_component()
        words[0] = words[0]
    end keep_component
end scoreboard Table
testbench Tb
    dut : Top
    table : Table
end testbench Tb
impl T for Tb
    run
        table.words[2] = 1
        wait 1 cycle
    end run
end impl T"#;
    let err = lower_src(base).expect_err("literal index equal to length is rejected");
    assert!(
        err.to_string().contains(
            "element index 2 is out of range for component `Vec` field `table.words` of length 2"
        ),
        "{err}"
    );

    let defaulted = base.replace(
        "words : Vec<uint<8>, 2>",
        "words : Vec<uint<8>, 2> default 0",
    );
    let err = lower_src(&defaulted).expect_err("aggregate default is rejected");
    let msg = err.to_string();
    assert!(
        msg.contains("default value on fixed-vector field `Table.words`"),
        "{msg}"
    );
}

#[test]
fn component_fixed_vec_whole_value_rules_and_metadata_are_checked() {
    let src = r#"scoreboard Table
    words : Vec<uint<64>, 4>
    flags : Vec<bool, 4>

    hookable keep_component()
        words[0] = words[0]
    end keep_component
end scoreboard Table

testbench Tb
    dut : Top
    a : Table
    b : Table
end testbench Tb

impl T for Tb
    run
        a.words = b.words
        assert a.words == b.words else fail("copy")
        wait 1 cycle
    end run
end impl T"#;

    let prog = lower_src(src).expect("same-shape component vectors lower");
    verify::verify_program(&prog).expect("whole-vector component IR verifies");
    let v1 = cpp_tb::emit(&merged_src(src)).expect("v1 emits the same array operations");
    let tbir = emit_cpp_src(src);
    for (v1_rendered, tbir_rendered) in [
        ("_tb.a.words = _tb.b.words;", "a.words = b.words;"),
        ("_tb.a.words == _tb.b.words", "a.words == b.words"),
    ] {
        assert!(v1.contains(v1_rendered), "v1 emits `{v1_rendered}`:\n{v1}");
        assert!(
            tbir.contains(tbir_rendered),
            "tbir emits `{tbir_rendered}`:\n{tbir}"
        );
    }

    for bad in [
        "a.words = b.flags",
        "assert a.words == b.flags else fail(\"bad\")",
    ] {
        let bad_src = src.replacen("a.words = b.words", bad, 1);
        let err = lower_src(&bad_src).expect_err("mismatched whole vectors are not C++ values");
        let msg = assert_not_implemented(&err, lower::V1Status::EmitsUncompilable);
        assert!(msg.contains("whole-vector"), "`{bad}`: {msg}");
    }
    let naked = src.replacen("a.words = b.words", "let x = b.words", 1);
    let msg = assert_not_implemented(
        &lower_src(&naked).expect_err("a whole array cannot initialize a scalar local"),
        lower::V1Status::EmitsUncompilable,
    );
    assert!(msg.contains("whole-vector component field"), "{msg}");

    let index_leak = r#"transaction Row
    data : Vec<uint<64>, 4>
end transaction Row
transaction Bank
    tbl : Vec<Row, 2>
end transaction Bank
scoreboard Table
    words : Vec<uint<64>, 4>
    hookable keep_component()
        words[0] = words[0]
    end keep_component
end scoreboard Table
testbench Tb
    dut : Top
    a : Table
end testbench Tb
impl T for Tb
    run
        let bank : Bank
        a.words = bank.tbl[a.words].data
        wait 1 cycle
    end run
end impl T"#;
    let msg = assert_not_implemented(
        &lower_src(index_leak)
            .expect_err("whole-vector permission must not leak into an index expression"),
        lower::V1Status::EmitsUncompilable,
    );
    assert!(
        msg.contains("whole-vector component field `a.words`"),
        "{msg}"
    );

    fn corrupt<F>(mut prog: ir::TbProgram, mutate: F)
    where
        F: FnOnce(&mut ir::ComponentBase, &mut String, &mut ir::Expr),
    {
        let (base, field, value) = prog
            .functions
            .iter_mut()
            .flat_map(|func| func.blocks.iter_mut())
            .flat_map(|block| block.stmts.iter_mut())
            .find_map(|stmt| match stmt {
                ir::Stmt::ComponentFieldWrite { base, field, value } => Some((base, field, value)),
                _ => None,
            })
            .expect("fixture contains a whole-vector write");
        mutate(base, field, value);
        assert!(
            verify::verify_program(&prog).is_err(),
            "corrupted component-vector metadata must not verify"
        );
    }

    corrupt(prog.clone(), |_, field, _| *field = "missing".to_string());
    corrupt(prog.clone(), |base, _, _| {
        *base = ir::ComponentBase::Local(ir::LocalId(0))
    });
    corrupt(prog.clone(), |_, _, value| match value {
        ir::Expr::ComponentField { field, .. } => *field = "flags".to_string(),
        other => panic!("whole-vector RHS is not a component field: {other:?}"),
    });
    corrupt(prog.clone(), |_, _, value| {
        *value = ir::Expr::Literal {
            value: 0,
            ty: ir::IrType::UInt(None),
        }
    });
    corrupt(prog.clone(), |_, field, _| *field = "flags".to_string());

    fn corrupt_equality<F>(mut prog: ir::TbProgram, mutate: F)
    where
        F: FnOnce(&mut ir::BinOp, &mut ir::Expr, &mut ir::Expr),
    {
        let cond = prog
            .functions
            .iter_mut()
            .flat_map(|func| func.blocks.iter_mut())
            .flat_map(|block| block.stmts.iter_mut())
            .find_map(|stmt| match stmt {
                ir::Stmt::AssertCheck { cond, .. } => Some(cond),
                _ => None,
            })
            .expect("fixture contains a vector equality");
        let ir::Expr::Binary(op, lhs, rhs) = cond else {
            panic!("vector equality did not lower to Binary: {cond:?}")
        };
        mutate(op, lhs, rhs);
        assert!(
            verify::verify_program(&prog).is_err(),
            "corrupted whole-vector equality must not verify"
        );
    }
    corrupt_equality(prog.clone(), |op, _, _| *op = ir::BinOp::Add);
    corrupt_equality(prog, |_, _, rhs| match rhs {
        ir::Expr::ComponentField { field, .. } => *field = "flags".to_string(),
        other => panic!("whole-vector equality RHS is not a component field: {other:?}"),
    });
}

#[test]
fn component_fixed_vec_side_table_predicates_are_verified() {
    let src = r#"property words_equal
    a.words == b.words
end property words_equal

scoreboard Table
    words : Vec<uint<64>, 4>
    flags : Vec<bool, 4>

    hookable keep_component()
        words[0] = words[0]
    end keep_component
end scoreboard Table

testbench Tb
    dut : Top
    a : Table
    b : Table
end testbench Tb

impl T for Tb
    run
        assert property words_equal
        cover a.words == b.words
        on a.words == b.words
            log(info, "equal")
        end on
        wait 1 cycle
    end run
end impl T"#;

    let prog = lower_src(src).expect("whole-vector side-table predicates lower");
    verify::verify_program(&prog).expect("whole-vector side-table predicates verify");
    assert_eq!(prog.property_checks.len(), 1);
    assert_eq!(prog.cover_checks.len(), 1);
    assert_eq!(prog.cycle_handlers.len(), 1);

    fn set_add(expr: &mut ir::Expr) {
        let ir::Expr::Binary(op, _, _) = expr else {
            panic!("whole-vector predicate is not binary: {expr:?}")
        };
        *op = ir::BinOp::Add;
    }

    let mut bad_property = prog.clone();
    match &mut bad_property.property_checks[0].shape {
        ir::PropertyShape::Invariant(expr) => set_add(expr),
        other => panic!("whole-vector property is not invariant: {other:?}"),
    }
    assert!(
        verify::verify_program(&bad_property).is_err(),
        "corrupted property side-table predicate must not verify"
    );

    let mut bad_cover = prog.clone();
    set_add(&mut bad_cover.cover_checks[0].cond);
    assert!(
        verify::verify_program(&bad_cover).is_err(),
        "corrupted cover side-table predicate must not verify"
    );

    let mut bad_handler = prog.clone();
    let ir::CycleHandlerKind::Trigger { trigger, .. } = &mut bad_handler.cycle_handlers[0].kind
    else {
        panic!("whole-vector cycle handler is not trigger-based")
    };
    let ir::Expr::Binary(_, _, rhs) = trigger else {
        panic!("whole-vector cycle trigger is not binary: {trigger:?}")
    };
    let ir::Expr::ComponentField { field, .. } = &mut **rhs else {
        panic!("whole-vector cycle trigger RHS is not a component field: {rhs:?}")
    };
    *field = "flags".to_string();
    assert!(
        verify::verify_program(&bad_handler).is_err(),
        "cross-lane cycle-handler predicate must not verify"
    );
}

#[test]
fn side_table_local_reads_obey_registration_point_dominance() {
    let src = r#"test T
    let dut : Top
    run
        let x = 3
        assert past(x) == 3 else fail("x=${x}")
        cover x == 3
        on x == 3
            log(info, "x")
        end on
        let y = 4
        wait 1 cycle
    end run
end test T"#;

    let prog = lower_src(src).expect("local-capturing side tables lower");
    verify::verify_program(&prog).expect("defined local captures verify");
    let run = prog.tests[0].run;
    let y = prog
        .function(run)
        .locals
        .iter()
        .position(|l| l.name == "y")
        .map(|index| ir::LocalId(index as u32))
        .unwrap();

    let assert_use_before_def = |bad: ir::TbProgram, site: &str| {
        let errs = verify::verify_program(&bad).expect_err(site);
        assert!(
            errs.iter().any(|err| matches!(
                err,
                verify::VerifyError::LocalUseBeforeDef { local, .. } if *local == y
            )),
            "{site}: {errs:?}"
        );
    };

    let mut bad_root = prog.clone();
    let ir::PropertyShape::Invariant(root) = &mut bad_root.property_checks[0].shape else {
        panic!("temporal equality did not lower as an invariant")
    };
    *root = ir::Expr::Local(y);
    assert_use_before_def(bad_root, "later local in property root must not verify");

    let mut bad_temporal = prog.clone();
    bad_temporal.property_checks[0].temporals[0].inner = ir::Expr::Local(y);
    assert_use_before_def(
        bad_temporal,
        "later local in temporal operand must not verify",
    );

    let mut bad_message = prog.clone();
    bad_message.property_checks[0]
        .message
        .as_mut()
        .expect("fixture has a property message")
        .args[0]
        .expr = ir::Expr::Local(y);
    assert_use_before_def(
        bad_message,
        "later local in property message must not verify",
    );

    let mut bad_cover = prog.clone();
    bad_cover.cover_checks[0].cond = ir::Expr::Local(y);
    assert_use_before_def(bad_cover, "later local in cover root must not verify");

    let mut bad_handler = prog;
    let ir::CycleHandlerKind::Trigger { trigger, .. } = &mut bad_handler.cycle_handlers[0].kind
    else {
        panic!("fixture cycle handler is not trigger-based")
    };
    *trigger = ir::Expr::Local(y);
    assert_use_before_def(
        bad_handler,
        "later local in cycle-handler root must not verify",
    );
}

#[test]
fn nested_self_component_vec_preserves_element_width_and_signedness() {
    let src = r#"scoreboard Leaf
    bytes : Vec<uint<8>, 2>
    signed_values : Vec<sint<8>, 2>
    hookable seed()
        bytes[0] = bytes[0]
    end seed
end scoreboard Leaf

scoreboard Parent
    child : Leaf
    inverted : uint<8> default 0
    shifted : sint<8> default 0
    hookable update()
        inverted = ~child.bytes[0]
        shifted = child.signed_values[0] >> 1
    end update
end scoreboard Parent

testbench Tb
    dut : Top
    parent : Parent
end testbench Tb

impl T for Tb
    run
        parent.child.bytes[0] = 0
        parent.child.signed_values[0] = -8
        parent.update()
        assert parent.inverted == 255 else fail("narrow bit-not")
        assert parent.shifted == -4 else fail("signed shift")
        wait 1 cycle
    end run
end impl T"#;
    let cpp = emit_cpp_src(src);
    assert!(
        cpp.contains("~(self.child.bytes[0]) & 0xFFULL"),
        "nested vector width must drive bit-not masking:\n{cpp}"
    );
    assert!(
        cpp.contains("((int64_t)(self.child.signed_values[0])) >> 1"),
        "nested signed vector element must use arithmetic shift:\n{cpp}"
    );
}

#[test]
fn test_scope_component_named_self_keeps_vector_element_metadata() {
    let src = r#"scoreboard Values
    signed_values : Vec<sint<8>, 1>
    hookable seed()
        signed_values[0] = signed_values[0]
    end seed
end scoreboard Values
testbench Tb
    dut : Top
    self : Values
end testbench Tb
impl T for Tb
    run
        self.signed_values[0] = -8
        assert (self.signed_values[0] >> 1) == -4 else fail("signed shift")
        wait 1 cycle
    end run
end impl T"#;
    let cpp = emit_cpp_src(src);
    assert!(
        cpp.contains("((int64_t)(self.signed_values[0])) >> 1"),
        "a real test-scope `self` binding must win over the component sentinel:\n{cpp}"
    );
}

/// A declared scalar field wider than 64 bits, at each of the four
/// emitters that render one.
///
/// All four carried their own copy of a `(bool | int64_t | uint64_t)`
/// type choice. A `uint<128>` member reaching any of them without the
/// shared `field_scalar_cty` seam is not a build failure — it is a
/// 64-bit member that compiles, runs, and drops the top half. Nothing
/// in the differential harness can see that, so the member type is
/// asserted here directly.
#[test]
fn a_wide_scalar_field_keeps_its_width_at_every_field_emitter() {
    // (source, expected member declaration) per emitter. `uint<1024>`
    // crosses from `_harc_u128` into `harc_rt::HarcWide<32>`, so each
    // emitter is checked on both sides of that boundary.
    for (width, cty) in [(128u32, "_harc_u128"), (1024, "harc_rt::HarcWide<32>")] {
        // 1. The testbench `_tb` struct.
        let tb = format!(
            "testbench Tb\n    dut : Top\n    w : uint<{width}> default 1\nend testbench Tb\n\
             \nimpl T for Tb\n    run\n        w = 2\n    end run\nend impl T\n"
        );
        assert!(
            emit_cpp_src(&tb).contains(&format!("{cty} w = 1;")),
            "testbench field at {width} bits must be `{cty}`"
        );

        // 2. The scoreboard struct.
        let sb = format!(
            "scoreboard Sb\n    w : uint<{width}> default 1\nend scoreboard Sb\n\
             \ntestbench Tb\n    dut : Top\n    sb : Sb\nend testbench Tb\n\
             \nimpl T for Tb\n    run\n        sb.w = 2\n    end run\nend impl T\n"
        );
        assert!(
            emit_cpp_src(&sb).contains(&format!("{cty} w = 1;")),
            "scoreboard field at {width} bits must be `{cty}`"
        );

        // 3. The component struct (an unbound transactor as a member).
        let comp = format!(
            "transactor Src\n    w : uint<{width}> default 1\n\
             \n    hookable bump(v: uint<8>)\n        w = w + 1\n    end bump\nend transactor Src\n\
             \ntestbench Tb\n    dut : Top\n    src : Src passive\nend testbench Tb\n\
             \nimpl T for Tb\n    run\n        src.bump(1)\n    end run\nend impl T\n"
        );
        assert!(
            emit_cpp_src(&comp).contains(&format!("{cty} w = 1;")),
            "component field at {width} bits must be `{cty}`"
        );

        // 4. The per-instance transactor-state struct.
        let state = format!(
            "bus TlmMemBus\n    tlm_method read(addr: uint<8>) -> uint<32>: blocking;\n\
             end bus TlmMemBus\n\
             \ntransactor TlmMemTarget bound to TlmMemBus\n    w : uint<{width}> default 1\n\
             \n    thread bus.read(addr: uint<8>)\n        w = w + 1\n        return 1\n\
             \n    end thread\nend transactor TlmMemTarget\n\
             \ntestbench Tb\n    dut : TlmReadInitiator\nend testbench Tb\n\
             \nimpl T for Tb\n    let mem : TlmMemBus = bind dut\n\
             \n    let target : TlmMemTarget passive = bind mem\n    run\n        wait 1 cycle\n\
             \n    end run\nend impl T\n"
        );
        assert!(
            emit_cpp_src(&state).contains(&format!("{cty} w = 1;")),
            "transactor state field at {width} bits must be `{cty}`"
        );
    }
}

/// A DIRECTION on a component field, at every arm that carries the
/// guard.
///
/// The arms answer `Unsupported` — "re-run with `--codegen v1`". v1
/// does compile all five, which is why the label survived four review
/// rounds. What it does is DISCARD the direction: emit the member for
/// the field's own type, exactly as if the marker were not there. That
/// is not an escape hatch, it is a program that means something else,
/// and it is what `SilentlyMisLowers` is for.
///
/// Proved by byte-identity against the undirected spelling, with the
/// two sources padded to the SAME length so no source-offset residue
/// can explain it — the technique the `bound to` field arm already
/// uses two hundred lines away.
#[test]
fn a_direction_on_a_component_field_is_discarded_by_v1() {
    let prog = |field: &str| {
        format!(
            r#"struct Beat
    p : uint<8>
end struct Beat

transactor Src
    n : uint<32> default 0
{field}
    hookable bump(v: uint<8>)
        n = n + 1
    end bump
end transactor Src

testbench TbDir
    dut : Top
    src : Src passive
end testbench TbDir

impl TDir for TbDir
    run
        src.bump(1)
        wait 1 cycle
    end run
end impl TDir
"#
        )
    };

    for (directional, undirected) in [
        ("    x : in uint<8>", "    x :    uint<8>"),
        ("    x : out uint<8>", "    x :     uint<8>"),
        ("    q : in queue<uint<8>>", "    q :    queue<uint<8>>"),
        ("    v : in Vec<uint<8>, 4>", "    v :    Vec<uint<8>, 4>"),
        ("    r : in Beat", "    r :    Beat"),
    ] {
        assert_eq!(
            directional.len(),
            undirected.len(),
            "the two spellings must be the same length for byte-identity to mean anything"
        );
        let with = cpp_tb::emit(&merged_src(&prog(directional))).expect("v1 emits the directional");
        let without = cpp_tb::emit(&merged_src(&prog(undirected))).expect("v1 emits the plain one");
        assert_eq!(
            with, without,
            "`{directional}`: v1's output must be byte-identical to the undirected \
             spelling — that identity is the whole evidence for the grade"
        );
        // …and tbir refuses it, on that grade.
        let err = lower_src(&prog(directional)).unwrap_err();
        let msg = assert_not_implemented(&err, lower::V1Status::SilentlyMisLowers);
        assert!(
            msg.contains("direction"),
            "`{directional}`: the reason must name the direction, got `{msg}`"
        );
        assert!(
            msg.len() > 40,
            "`{directional}`: three of these arms shipped an EMPTY reason string"
        );
    }
}

/// Wide scalar state on a METHOD-BEARING component — the four seams
/// issue #642 named, each of which truncates SILENTLY on its own.
///
/// Lifting the field-width cap (#653) was only the first of them. The
/// other three all read or write the same wide field through a path
/// that had its own hardcoded 64-bit assumption, so a partial fix moved
/// the failure from a clear lowering diagnostic to a low-word copy that
/// compiles, runs, and quietly answers wrong.
#[test]
fn wide_component_scalar_state_keeps_its_declared_type_at_every_seam() {
    let prog = lower_src(&fixture("component_wide_scalar_state_test.harc"))
        .expect("wide component scalar state lowers");
    verify::verify_program(&prog).expect("wide component scalar state verifies");

    let local_ty = |func: &ir::TbFunction, name: &str| {
        func.locals
            .iter()
            .find(|l| l.name == name)
            .unwrap_or_else(|| panic!("local `{name}` is missing"))
            .ty
            .clone()
    };
    let run = prog
        .functions
        .iter()
        .find(|f| matches!(f.kind, ir::FunctionKind::Run { .. }))
        .expect("the run body is lowered");

    // Seam 2 — an UNTYPED read takes the field's exact type. Before
    // this, `expr_type` had no `Expr::ComponentField` arm, the local
    // declared `uint64_t`, and the copy kept the low word. Each of the
    // three widths exercises a different C++ carrier: `HarcWide<8>`,
    // `HarcWide<7>` (non-word-aligned), `_harc_u128`.
    for (name, want) in [
        ("observed", ir::IrType::UInt(Some(256))),
        ("odd_observed", ir::IrType::UInt(Some(200))),
        ("medium_observed", ir::IrType::UInt(Some(65))),
    ] {
        assert_eq!(
            local_ty(run, name),
            want,
            "an untyped read of a wide component field must take the field's type"
        );
    }

    // Seam 4 — and so does an untyped destination of a wide method
    // CALL, which survives fixing the lambda's own return type.
    assert_eq!(
        local_ty(run, "odd_via_method"),
        ir::IrType::UInt(Some(200)),
        "an untyped wide method result must take the method's return type"
    );

    // Seam 3 — the hidden `__ret` slot carries the DECLARED return
    // type, which is what the emitter renders the lambda's return type
    // from. Only the record half of this used to be typed.
    let returns: Vec<ir::IrType> = prog
        .functions
        .iter()
        .filter_map(|f| f.ret.map(|r| f.locals[r.index()].ty.clone()))
        .collect();
    assert!(
        returns.contains(&ir::IrType::UInt(Some(256)))
            && returns.contains(&ir::IrType::UInt(Some(200))),
        "component-method `__ret` slots must carry their declared wide types, got {returns:?}"
    );
}

/// A write into a wide component field follows the same directional
/// assignment rule a data-only scoreboard field already followed.
///
/// The two carriers make this necessary rather than merely tidy:
/// `uint<129>` and `uint<65>` are BOTH `_harc_u128`, so C++ takes the
/// assignment and leaves the bits above 65 live in storage. There is no
/// compiler error to fall back on and no runtime check — only this
/// diagnostic stands between the user and a checker that silently keeps
/// bits it does not have.
#[test]
fn a_wide_component_field_write_is_checked_for_width_and_signedness() {
    let prog = |field: &str, param: &str| {
        format!(
            "scoreboard NarrowState\n    \
                 value : {field} default 0\n\n    \
                 hookable write(v: {param})\n        \
                     value = v\n    \
                 end write\n\
             end scoreboard NarrowState\n\n\
             testbench NarrowTb\n    dut : Top\n    n : NarrowState\n\
             end testbench NarrowTb\n\n\
             impl NarrowTest for NarrowTb\n    run\n        wait 1 cycle\n    end run\n\
             end impl NarrowTest\n"
        )
    };

    // Same carrier (`_harc_u128`), different declared widths.
    let err = lower_src(&prog("uint<65>", "uint<129>"))
        .expect_err("an implicit narrowing into a wide component field is refused");
    let msg = err.to_string();
    assert!(
        matches!(err, lower::LowerError::Invalid(_))
            && msg.contains("assignment of a 129-bit value")
            && msg.contains("component field `value`, declared 65 bits")
            && msg.contains("narrows"),
        "the diagnostic must name both widths and the destination: {msg}"
    );

    // Matching carriers do not make the language types interchangeable.
    let err = lower_src(&prog("uint<65>", "sint<32>"))
        .expect_err("an implicit signedness change is refused");
    let msg = err.to_string();
    assert!(
        msg.contains("component field `value`") && msg.contains("Signedness must match"),
        "a signedness change must be diagnosed separately from a width change: {msg}"
    );

    // Legal widening is untouched, in both directions of the carrier
    // boundary (`_harc_u128` → `HarcWide<5>`, and within one carrier).
    for (field, param) in [
        ("uint<129>", "uint<65>"),
        ("uint<256>", "uint<129>"),
        ("uint<129>", "uint<129>"),
    ] {
        let widening = lower_src(&prog(field, param));
        assert!(
            widening.is_ok(),
            "`{param}` into `{field}` widens and must lower: {:?}",
            widening.err()
        );
    }

    // The ORDINARY counting idiom stays legal. `common_expr_type`
    // gives a widthless operand the 64-bit host ABI, so a sum can type
    // as 64 bits whatever its destination is; a ≤64-bit destination is
    // therefore NOT judged here, and a destination past 64 cannot be
    // narrowed by that manufactured 64, which is what keeps the check
    // above resting only on declared widths. See the follow-up issue
    // for the ≤64-bit half.
    //
    // This comment named the `on ev(t)` payload param as THE widthless
    // operand ("`EventPayload::Scalar` records signedness only"). The
    // payload carries its width now, so `t` here is `uint<8>` and the
    // row survives for a different reason: `seen` is `uint<32>`, which
    // the guard does not judge either way.
    let counter = "domain SysDomain\n  freq_mhz: 100\nend domain SysDomain\n\n\
         agent Tagger\n    \
             in_ev : event<uint<8>>\n    \
             seen  : uint<32> default 0\n\n    \
             on in_ev(t)\n        seen = seen + t\n    end on\n\
         end agent Tagger\n\n\
         test T\n    let dut : Top\n    let tagger : Tagger\n    clock clk = SysDomain\n    \
             run\n        wait 2 cycles\n        emit tagger.in_ev(1)\n        \
                 wait 2 cycles\n    end run\n\
         end test T\n";
    lower_src(counter).expect("`seen = seen + t` on an event payload param stays legal");
}

/// A fixed-vector ELEMENT wider than 64 bits keeps its width in the
/// emitted member.
///
/// The differential harness typechecks both backends, and
/// `std::array<uint64_t, 4>` for a `Vec<uint<1024>, 4>` compiles
/// perfectly — it just keeps a sixteenth of each element. Only the
/// member TEXT distinguishes the fix from the bug it replaced, so it is
/// asserted here, against v1's own answer.
#[test]
fn a_wide_fixed_vector_element_keeps_its_width() {
    let prog = |ty: &str| {
        format!(
            r#"transactor SrcV
    v : Vec<{ty}, 4>
    n : uint<32> default 0

    hookable bump(x: uint<8>)
        v[0] = 1
        n = n + 1
    end bump
end transactor SrcV

testbench TbWv
    dut : Top
    src : SrcV passive
end testbench TbWv

impl TWv for TbWv
    run
        src.bump(1)
        wait 1 cycle
    end run
end impl TWv
"#
        )
    };
    for (ty, member) in [
        ("uint<8>", "std::array<uint64_t, 4> v{};"),
        ("uint<64>", "std::array<uint64_t, 4> v{};"),
        ("uint<128>", "std::array<_harc_u128, 4> v{};"),
        ("uint<1024>", "std::array<harc_rt::HarcWide<32>, 4> v{};"),
        ("sint<64>", "std::array<int64_t, 4> v{};"),
        ("bool", "std::array<bool, 4> v{};"),
    ] {
        let src = prog(ty);
        let cpp = emit_cpp_src(&src);
        assert!(
            cpp.contains(member),
            "`Vec<{ty}, 4>`: tbir must emit `{member}`, got:\n{cpp}"
        );
        // v1 is the oracle for the member, not this test's memory of it.
        assert!(
            cpp_tb::emit(&merged_src(&src))
                .expect("v1 emits")
                .contains(member),
            "`Vec<{ty}, 4>`: v1 emits `{member}` too — the two agree"
        );
    }
}

/// A wide event PAYLOAD keeps its width in the subscriber's parameter
/// type, at both emitters that render one.
///
/// `EventPayload::Scalar` carried a lone `signed: bool` until this
/// batch, so `uint64_t` and `int64_t` were the only two things it could
/// mean and a `std::function<void(uint64_t)>` for an
/// `event<uint<1024>>` would have compiled while dropping fifteen
/// sixteenths of every notification. Only the member TEXT tells the fix
/// from that bug, so it is asserted against v1's own answer.
#[test]
fn a_wide_event_payload_keeps_its_width() {
    let prog = |ty: &str| {
        format!(
            r#"transactor SrcE
    ev : out event<{ty}>
    n  : uint<32> default 0

    hookable bump(v: uint<8>)
        n = n + 1
    end bump
end transactor SrcE

testbench TbWe
    dut : Top
    src : SrcE passive
end testbench TbWe

impl TWe for TbWe
    run
        src.bump(1)
        wait 1 cycle
    end run
end impl TWe
"#
        )
    };
    // (payload, what tbir emits, what v1 emits). The two agree
    // everywhere except `bool`, which is NOT this batch's doing and is
    // recorded rather than quietly asserted away: v1 gives a bool
    // payload `std::function<void(bool)>` and tbir gives
    // `void(uint64_t)`. Both compile, so no differential space can see
    // it; the observable difference is that `emit ev(2)` notifies with
    // `true` under v1 and `2` here. Closing it needs the payload
    // schema to be able to SAY bool — `{ signed, width }` cannot, since
    // `width: Some(1)` means `uint<1>`, which v1 renders `uint64_t`.
    for (ty, member, v1_member) in [
        (
            "uint<8>",
            "std::vector<std::function<void(uint64_t)>> ev;",
            "std::vector<std::function<void(uint64_t)>> ev;",
        ),
        (
            "sint<32>",
            "std::vector<std::function<void(int64_t)>> ev;",
            "std::vector<std::function<void(int64_t)>> ev;",
        ),
        (
            "bool",
            "std::vector<std::function<void(uint64_t)>> ev;",
            "std::vector<std::function<void(bool)>> ev;",
        ),
        (
            "uint<128>",
            "std::vector<std::function<void(_harc_u128)>> ev;",
            "std::vector<std::function<void(_harc_u128)>> ev;",
        ),
        (
            "uint<1024>",
            "std::vector<std::function<void(harc_rt::HarcWide<32>)>> ev;",
            "std::vector<std::function<void(harc_rt::HarcWide<32>)>> ev;",
        ),
    ] {
        let src = prog(ty);
        let cpp = emit_cpp_src(&src);
        assert!(
            cpp.contains(member),
            "`event<{ty}>`: tbir must emit `{member}`, got:\n{cpp}"
        );
        assert!(
            cpp_tb::emit(&merged_src(&src))
                .expect("v1 emits")
                .contains(v1_member),
            "`event<{ty}>`: v1 must emit `{v1_member}`"
        );
    }
}

/// The IR dump names a component scalar field's EXACT type.
///
/// Every other field kind already printed what it holds; the scalar
/// kind printed the word "scalar", so a `uint<256>` field and a
/// `uint<8>` field rendered identically — and which of the three
/// storage classes the emitter picks (`uint64_t`, `_harc_u128`,
/// `harc_rt::HarcWide<N>`) is exactly what every seam in harc#642
/// turned on.
#[test]
fn the_ir_dump_names_a_component_scalar_fields_exact_type() {
    let prog = lower_src(&fixture("component_wide_scalar_state_test.harc"))
        .expect("wide component scalar state lowers");
    let dump = format!("{prog}");
    for want in [
        "field value : uint<256> = 0",
        "field odd : uint<200> = 0",
        "field medium : uint<65> = 0",
    ] {
        assert!(
            dump.contains(want),
            "the dump must name the field's exact type — missing `{want}`:\n{dump}"
        );
    }
    assert!(
        !dump.contains(": scalar = "),
        "no component scalar field should still render as the bare word `scalar`:\n{dump}"
    );
}

/// The verifier is the IR-level backstop for the directional write rule
/// lowering enforces — and is bounded to the same widths lowering is.
///
/// Both halves matter. Without the check, a `uint<129>` written into a
/// `uint<65>` field passes the verifier untouched and both sides are
/// `_harc_u128` in C++, so nothing downstream objects either. With the
/// check UNBOUNDED, `uint<32>` into a `uint<8>` field — which lowering
/// deliberately still accepts, pending #658 — becomes `internal error:
/// TB-IR failed verification after lowering`, which is strictly worse
/// than what it replaced: an internal error for source `harc check`
/// accepts. The first version of this arm did exactly that.
#[test]
fn the_verifier_backstops_wide_component_field_writes_at_lowerings_bound() {
    let mut broken = lower_src(&fixture("component_wide_scalar_state_test.harc"))
        .expect("wide component scalar state lowers");
    verify::verify_program(&broken).expect("the unmodified fixture verifies");

    // `medium` is `uint<65>`. A 129-bit value shares its `_harc_u128`
    // carrier, so only this check stands between it and storage that
    // keeps bits the field does not have.
    let run = broken.tests[0].run.index();
    let write = broken.functions[run]
        .blocks
        .iter_mut()
        .flat_map(|block| &mut block.stmts)
        .find_map(|stmt| match stmt {
            ir::Stmt::ComponentFieldWrite { field, value, .. } if field == "medium" => Some(value),
            _ => None,
        })
        .expect("the fixture writes the 65-bit field");
    *write = ir::Expr::WideLiteral(vec![0, 0, 0, 0, 1]);
    let rendered = verify::verify_program(&broken)
        .expect_err("a 129-bit value cannot enter a 65-bit component field")
        .into_iter()
        .map(|err| err.to_string())
        .collect::<Vec<_>>()
        .join("\n");
    assert!(
        rendered.contains(
            "writes UInt(Some(129)) into component field `medium` declared UInt(Some(65))"
        ),
        "the write error must record the assignment direction: {rendered}"
    );

    // …and the verifier stays a >64 backstop even though lowering now
    // judges <=64-bit fields too (harc#658). A VALID <=64 write must
    // lower and verify cleanly — the verifier must not over-reject the
    // width range it deliberately leaves to lowering. (The <=64
    // NARROWING refusal itself is lowering's, covered by
    // `a_le64_component_field_write_is_checked_without_manufactured_widths`.)
    let sub64 = r#"scoreboard SmallState
    v : uint<8> default 0

    hookable put(x: uint<8>)
        v = x
    end put
end scoreboard SmallState

testbench SmallTb
    dut : Top
    s : SmallState
end testbench SmallTb

impl SmallTest for SmallTb
    run
        wait 1 cycle
    end run
end impl SmallTest
"#;
    let prog = lower_src(sub64).expect("a valid <=64-bit component field write lowers");
    verify::verify_program(&prog)
        .expect("the verifier must accept a valid <=64-bit component field write");
}

/// Two scalar event payloads of DIFFERENT declared widths still
/// `connect`, exactly as they did before the payload schema carried a
/// width.
///
/// `EventPayload` derives `PartialEq`, and the event-sink branch asked
/// `*payload != src_payload`. The moment the variant grew a `width`
/// that struct equality silently became a width check, so
/// `event<uint<8>> -> event<uint<16>>` — two payloads v1 renders as
/// the same `std::function<void(uint64_t)>` — started reporting "source
/// and sink scalar payloads must agree in signedness", a message that
/// is false about a program whose signedness agrees.
///
/// The rows are the ones measured against `origin/main`'s own binary:
/// all of them lower there. Signedness disagreement is the rule that
/// arm really enforces, so it stays refused.
///
/// TESTBENCH scope, and `verify_program`, both deliberately. The first
/// version of this test wired the connect inside an `env` and called
/// `lower_src`, which stops at lowering — and `verify.rs` walks only
/// `tb.connects`, so an `env` connect reaches no verifier at all. That
/// combination missed the twin of the very bug this test exists for:
/// `verify.rs` compared whole `EventPayload` values too, so lowering
/// emitted the edge and the verifier rejected it, one `internal error:
/// TB-IR failed verification after lowering` per row. Both scopes run
/// here now, both through the verifier.
#[test]
fn a_connect_between_two_scalar_event_widths_still_lowers() {
    let env_prog = |src: &str, sink: &str| {
        format!(
            r#"transactor SrcT
    observed : out event<{src}>
    n : uint<32> default 0
    hookable publish(v: uint<8>)
        n = n + 1
    end publish
end transactor SrcT

transactor RelayT
    inev : event<{sink}>
    m : uint<32> default 0
    hookable poke(v: uint<8>)
        m = m + 1
    end poke
end transactor RelayT

env ConnEnv
    source : SrcT passive
    relay  : RelayT passive
    connect
        source.observed -> relay.inev
    end connect
end env ConnEnv

test ConnTest
    let dut : Top
    let env : ConnEnv
    run
        env.source.publish(1)
        wait 1 cycle
    end run
end test ConnTest
"#
        )
    };
    let tb_prog = |src: &str, sink: &str| {
        format!(
            r#"transactor SrcTb
    observed : out event<{src}>
    n : uint<32> default 0
    hookable publish(v: uint<8>)
        n = n + 1
    end publish
end transactor SrcTb

transactor RelayTb
    inev : event<{sink}>
    m : uint<32> default 0
    hookable poke(v: uint<8>)
        m = m + 1
    end poke
end transactor RelayTb

testbench TbConn
    dut : Top
    source : SrcTb passive
    relay  : RelayTb passive
    connect
        source.observed -> relay.inev
    end connect
end testbench TbConn

impl TConn for TbConn
    run
        source.publish(1)
        wait 1 cycle
    end run
end impl TConn
"#
        )
    };
    for (src, sink) in [
        ("uint<8>", "uint<8>"),
        ("uint<8>", "uint<16>"),
        ("uint<8>", "uint"),
        ("uint", "uint<8>"),
        ("uint", "uint<64>"),
        ("bool", "uint<1>"),
        ("uint<1>", "bool"),
        ("sint<8>", "sint<64>"),
        ("sint<64>", "sint<8>"),
        ("uint<128>", "uint<128>"),
        ("uint<160>", "uint<1024>"),
        ("uint<8>", "uint<1024>"),
    ] {
        for (scope, src_text) in [
            ("env", env_prog(src, sink)),
            ("testbench", tb_prog(src, sink)),
        ] {
            let prog = lower_src(&src_text).unwrap_or_else(|e| {
                panic!("`event<{src}> -> event<{sink}>` must lower at {scope} scope: {e:?}");
            });
            // The verifier is where the twin of this bug lived. A
            // program that lowers and fails verification is an
            // `internal error` from the CLI, which is strictly worse
            // than the refusal it replaced.
            verify::verify_program(&prog).unwrap_or_else(|e| {
                panic!("`event<{src}> -> event<{sink}>` must VERIFY at {scope} scope: {e:?}");
            });
        }
    }
    // The rule that arm DOES enforce. Without it the assertions above
    // would also pass with the whole check deleted.
    let err =
        lower_src(&env_prog("uint<8>", "sint<8>")).expect_err("signedness must still disagree");
    let msg = assert_unsupported(&err);
    assert!(
        msg.contains("agree in signedness"),
        "a signedness mismatch keeps its own diagnostic: {msg}"
    );
}

/// A `connect` whose payload is WIDER than the subscriber receiving it
/// is refused, at both sink kinds, and graded by what v1 does with the
/// bridge it emits anyway.
///
/// This became reachable only when the payload gate opened past 64
/// bits. v1's bridge is a generic lambda — `src.push_back([&](auto _t)
/// { for (auto& _s : sink) _s(_t); })` — so delivery is one C++
/// implicit conversion, and g++ `-std=gnu++20` was asked what each
/// conversion does:
///
///   - `HarcWide<32>` into `uint64_t` or `_harc_u128`: compiles, and
///     drops the high words with no diagnostic. `SilentlyMisLowers`.
///   - `HarcWide<32>` into `HarcWide<5>`: no such conversion exists, so
///     v1's bridge does not compile. `EmitsUncompilable`.
///
/// Widening is NOT refused: `HarcWide<5>` into `HarcWide<32>` was
/// measured to preserve every word (it does not round-trip through
/// `uint64_t`), and the widening rows are asserted in
/// `a_connect_between_two_scalar_event_widths_still_lowers`.
#[test]
fn a_connect_that_narrows_its_payload_is_refused() {
    let event_sink = |src: &str, sink: &str| {
        format!(
            r#"transactor SrcW
    observed : out event<{src}>
    n : uint<32> default 0
    hookable publish(v: uint<8>)
        n = n + 1
    end publish
end transactor SrcW

transactor RelayW
    inev : event<{sink}>
    m : uint<32> default 0
    hookable poke(v: uint<8>)
        m = m + 1
    end poke
end transactor RelayW

env NarrowEnv
    source : SrcW passive
    relay  : RelayW passive
    connect
        source.observed -> relay.inev
    end connect
end env NarrowEnv

test NarrowTest
    let dut : Top
    let env : NarrowEnv
    run
        env.source.publish(1)
        wait 1 cycle
    end run
end test NarrowTest
"#
        )
    };
    // TESTBENCH scope as well as `env` scope: `verify.rs` walks only
    // `tb.connects`, so an `env` connect never reaches the verifier and
    // a verdict measured only there says nothing about the path the
    // CLI takes.
    let tb_event_sink = |src: &str, sink: &str| {
        format!(
            r#"transactor SrcWTb
    observed : out event<{src}>
    n : uint<32> default 0
    hookable publish(v: uint<8>)
        n = n + 1
    end publish
end transactor SrcWTb

transactor RelayWTb
    inev : event<{sink}>
    m : uint<32> default 0
    hookable poke(v: uint<8>)
        m = m + 1
    end poke
end transactor RelayWTb

testbench NarrowTb
    dut : Top
    source : SrcWTb passive
    relay  : RelayWTb passive
    connect
        source.observed -> relay.inev
    end connect
end testbench NarrowTb

impl NarrowTbTest for NarrowTb
    run
        source.publish(1)
        wait 1 cycle
    end run
end impl NarrowTbTest
"#
        )
    };
    let method_sink = |src: &str, sink: &str| {
        fixture("analysis_sink_connect_test.harc")
            .replace("out event<uint<8>>", &format!("out event<{src}>"))
            .replace("write_obs(v: uint<8>)", &format!("write_obs(v: {sink})"))
            .replace("sample_obs(v: uint<8>)", &format!("sample_obs(v: {sink})"))
            .replace("sum = sum + v", "sum = sum + 1")
    };
    for (src, sink, v1) in [
        ("uint<128>", "uint<8>", lower::V1Status::SilentlyMisLowers),
        ("uint<1024>", "uint<8>", lower::V1Status::SilentlyMisLowers),
        (
            "uint<1024>",
            "uint<128>",
            lower::V1Status::SilentlyMisLowers,
        ),
        (
            "uint<1024>",
            "uint<160>",
            lower::V1Status::EmitsUncompilable,
        ),
    ] {
        for (label, src_text) in [
            ("env event sink", event_sink(src, sink)),
            ("testbench event sink", tb_event_sink(src, sink)),
            ("method sink", method_sink(src, sink)),
        ] {
            let err = lower_src(&src_text).err().unwrap_or_else(|| {
                panic!("`event<{src}>` into a `{sink}` {label} must be refused, not lowered")
            });
            let msg = assert_not_implemented(&err, v1);
            assert!(
                msg.contains("wider than the subscriber"),
                "`event<{src}>` -> `{sink}` ({label}): {msg}"
            );
        }
    }
}

/// The IR dump names an event payload's EXACT type.
///
/// `field observed : out event<uint>` was what a `uint<8>` payload and
/// a `uint<1024>` payload both printed — right beside a scalar field
/// that names its exact type, which is the discipline
/// `the_ir_dump_names_a_component_scalar_fields_exact_type` asserts a
/// few lines up. It also meant the `*_dump_ir` snapshot corpus was
/// structurally incapable of catching a payload-width regression: the
/// only line that could move was an `on` handler's parameter.
///
/// The COMPONENT-FIELD renderer is what this pins. `type_str`'s
/// `IrType::Event` arm was changed the same way and is NOT covered:
/// no probe here and no snapshot in `tests/snapshots/` renders an
/// `IrType::Event` through it. Saying so is better than a doc comment
/// claiming "both renderers" over one of them, which is what the first
/// version of this said.
///
/// The dump also prints `out` for EVERY event field, including an
/// input one — `inev : event<uint<16>>` dumps as `out
/// event<uint<16>>`. That is not this test's subject and not fixable
/// here: `ComponentFieldKind::Event { payload }` records no direction
/// at all, so the renderer has nothing to consult. Measured and left
/// alone rather than papered over.
#[test]
fn the_ir_dump_names_an_event_payloads_exact_type() {
    let prog = |ty: &str| {
        format!(
            r#"transactor DumpSrc
    observed : out event<{ty}>
    n : uint<32> default 0

    hookable publish(v: uint<8>)
        n = n + 1
    end publish
end transactor DumpSrc

testbench TbDump
    dut : Top
    src : DumpSrc passive
end testbench TbDump

impl TDump for TbDump
    run
        src.publish(1)
        wait 1 cycle
    end run
end impl TDump
"#
        )
    };
    for (ty, want) in [
        ("uint<8>", "field observed : out event<uint<8>>"),
        ("sint<32>", "field observed : out event<sint<32>>"),
        ("uint<1024>", "field observed : out event<uint<1024>>"),
        // `event<uint>` — a scalar payload with no declared width.
        ("uint", "field observed : out event<uint>"),
    ] {
        let dump = format!(
            "{}",
            lower_src(&prog(ty)).unwrap_or_else(|e| panic!("`event<{ty}>` lowers: {e:?}"))
        );
        assert!(
            dump.contains(want),
            "`event<{ty}>` must dump as `{want}`:\n{dump}"
        );
    }

    // A genuinely BARE `event`, with no type argument at all — a
    // different source shape from `event<uint>`, and the one that
    // would show a manufactured width if `scalar_ir_type()` invented
    // one for a `None`.
    let bare = prog("uint").replace("out event<uint>", "out event");
    // Without this the row is a no-op that still passes: the assertion
    // below is the same string `prog("uint")` already prints, so a
    // template edit that stopped matching the replace pattern would
    // silently degrade this into a duplicate of the row above — the
    // "looks like coverage" failure mode this file keeps finding.
    assert_ne!(
        bare,
        prog("uint"),
        "the bare-`event` substitution must actually change the source"
    );
    let dump = format!("{}", lower_src(&bare).expect("a bare `event` field lowers"));
    assert!(
        dump.contains("field observed : out event<uint>"),
        "a bare `event` must not acquire a width:\n{dump}"
    );
}

/// The verifier backstops the `connect` payload-width rule at BOTH
/// sink kinds — by asking lowering's predicate, not by restating it.
///
/// A backstop only earns its name against an IR lowering would not
/// produce, so this builds one: lower a valid connect, then widen the
/// SOURCE payload in the schema and hand the result to the verifier.
/// That is what a lowering site which forgot to call
/// `connect_delivery_verdict` would emit — and one did: with that call
/// deleted, `event<uint<1024>> -> observe(v: uint<8>)` lowered,
/// verified clean, and emitted a
/// `std::function<void(harc_rt::HarcWide<32>)>` feeding a `uint64_t`
/// parameter, dropping 960 bits per notification with no diagnostic.
///
/// Testbench scope on purpose. `verify.rs` walks `tb.connects` only,
/// so the same edge inside an `env` — the majority shape in the
/// fixture corpus — reaches no verifier at all. That hole is real and
/// is NOT closed here; this test pins the scope that is covered so the
/// coverage claim stays honest about which one it is.
#[test]
fn the_verifier_backstops_the_connect_payload_width_rule() {
    let widen_source_payload = |prog: &mut ir::TbProgram| {
        let payload = prog
            .components
            .iter_mut()
            .flat_map(|c| c.fields.iter_mut())
            .find_map(|f| match &mut f.kind {
                ir::ComponentFieldKind::Event { payload } => Some(payload),
                _ => None,
            })
            .expect("the source declares an event field");
        *payload = ir::EventPayload::Scalar {
            signed: false,
            width: Some(1024),
        };
    };

    // Sink kind 1: a hookable METHOD parameter.
    let method_sink = r#"transactor BackstopSrc
    observed : out event<uint<8>>
    n : uint<32> default 0
    hookable publish(v: uint<8>)
        n = n + 1
    end publish
end transactor BackstopSrc

scoreboard BackstopSb
    seen : uint<32> default 0
    hookable observe(v: uint<8>)
        seen = seen + 1
    end observe
end scoreboard BackstopSb

testbench BackstopTb
    dut : Top
    source : BackstopSrc passive
    sb     : BackstopSb
    connect
        source.observed -> sb.observe
    end connect
end testbench BackstopTb

impl BackstopTest for BackstopTb
    run
        source.publish(1)
        wait 1 cycle
    end run
end impl BackstopTest
"#;

    // Sink kind 2: another component's EVENT field.
    let event_sink = r#"transactor BackstopSrc2
    observed : out event<uint<8>>
    n : uint<32> default 0
    hookable publish(v: uint<8>)
        n = n + 1
    end publish
end transactor BackstopSrc2

transactor BackstopRelay
    inev : event<uint<8>>
    m : uint<32> default 0
    hookable poke(v: uint<8>)
        m = m + 1
    end poke
end transactor BackstopRelay

testbench BackstopTb2
    dut : Top
    source : BackstopSrc2 passive
    relay  : BackstopRelay passive
    connect
        source.observed -> relay.inev
    end connect
end testbench BackstopTb2

impl BackstopTest2 for BackstopTb2
    run
        source.publish(1)
        wait 1 cycle
    end run
end impl BackstopTest2
"#;

    for (kind, src) in [("method sink", method_sink), ("event sink", event_sink)] {
        let mut prog = lower_src(src).unwrap_or_else(|e| panic!("{kind} lowers: {e:?}"));
        verify::verify_program(&prog)
            .unwrap_or_else(|e| panic!("{kind} verifies before the widening: {e:?}"));
        widen_source_payload(&mut prog);
        verify::verify_program(&prog).expect_err(&format!(
            "{kind}: a 1024-bit payload cannot be delivered to a 64-bit subscriber"
        ));
    }
}

/// Field-declaration shapes that promised v1 (`Unsupported`) while v1
/// measurably mishandles them, THE SAME WAY at every landing. Each is
/// regraded to the honest `NotImplemented` grade its own siblings
/// already carry, and each row pins v1's ACTUAL emission so the grade
/// rests on what v1 does, not on a remembered claim.
///
/// - `Vec<T,N> default` → `EmitsUncompilable`. v1 emits the aggregate
///   default as a scalar initializer on a `std::array` member
///   (`= 0`), which g++ refuses. The sibling `queue`/`Record`/event
///   `default` arms already grade this way.
/// - `buffer`/`stream` → `SilentlyMisLowers`. v1 has no runtime for
///   either and emits a bare `uint64_t`, dropping the message-passing
///   semantics.
///
/// A DIRECTIONAL event field looked like a third row and is
/// deliberately absent: v1's behavior there splits by landing (a
/// subscriber list on a transactor, a bare `uint64_t` on a
/// scoreboard), so it is not a uniform mis-grade — the batch-45
/// lesson, caught here by a transactor test failing when it was
/// grouped in.
#[test]
fn misgraded_field_shapes_are_regraded_to_what_v1_actually_does() {
    let prog = |field: &str| {
        format!(
            r#"scoreboard Sb
    {field}
    n : uint<32> default 0
    hookable put(x: uint<8>)
        n = n + 1
    end put
end scoreboard Sb
testbench Tb
    dut : Top
    sb : Sb
end testbench Tb
impl T for Tb
    run
        wait 1 cycle
    end run
end impl T"#
        )
    };

    // (field decl, grade, a substring of v1's mislowered member).
    for (field, grade, v1_member) in [
        (
            "v : Vec<uint<8>, 2> default {0, 0}",
            lower::V1Status::EmitsUncompilable,
            "std::array<uint64_t, 2> v = 0",
        ),
        (
            "b : buffer<uint<8>>",
            lower::V1Status::SilentlyMisLowers,
            "uint64_t b",
        ),
        (
            "s : stream<uint<8>>",
            lower::V1Status::SilentlyMisLowers,
            "uint64_t s",
        ),
    ] {
        let src = prog(field);
        // tbir: the honest grade, and never the "re-run with v1" line.
        let err = lower_src(&src)
            .err()
            .unwrap_or_else(|| panic!("`{field}` must be refused, not lowered"));
        let msg = assert_not_implemented(&err, grade);
        assert!(
            !msg.contains("re-run with `--codegen v1`"),
            "`{field}` must not misdirect to v1: {msg}"
        );
        // v1: the mislowered member that JUSTIFIES the grade. Deriving
        // it from v1's own output rather than asserting a remembered
        // string is what keeps the grade measured.
        let cpp = cpp_tb::emit(&merged_src(&src)).expect("v1 emits");
        assert!(
            cpp.contains(v1_member),
            "`{field}`: v1 must emit `{v1_member}` (the mislowering the grade records):\n{}",
            cpp.lines()
                .filter(|l| l.contains("struct Sb")
                    || l.trim().starts_with("std::")
                    || l.contains("uint64_t "))
                .take(8)
                .collect::<Vec<_>>()
                .join("\n")
        );
    }
}

/// A NESTED fixed-vector component field `Vec<Vec<T, N>, M>` declares,
/// emits, reads, and writes end-to-end, matching v1 at every storage
/// class — and the sub-cases v1 itself cannot lower stay refused.
///
/// v1 emits `std::array<std::array<{leaf}, N>, M>` for the member and
/// `self.v[i][j]` for a two-level index; both derived here from v1's
/// own output rather than pasted, so the match is measured. The IR
/// carries the second index in `ComponentVecElement::inner_index` /
/// `ComponentVecElementWrite::inner_index`.
#[test]
fn a_nested_fixed_vector_component_field_matches_v1() {
    let prog = |elem: &str, body: &str| {
        format!(
            r#"scoreboard Sb
    v : Vec<Vec<{elem}, 2>, 2>
    n : uint<1024> default 0
    hookable put(x: uint<8>)
        {body}
    end put
end scoreboard Sb
testbench Tb
    dut : Top
    sb : Sb
end testbench Tb
impl T for Tb
    run
        wait 1 cycle
    end run
end impl T"#
        )
    };

    // The member's C++ storage, per leaf class, against v1's own emit.
    for (elem, member) in [
        ("uint<8>", "std::array<std::array<uint64_t, 2>, 2> v{};"),
        ("sint<8>", "std::array<std::array<int64_t, 2>, 2> v{};"),
        ("uint<128>", "std::array<std::array<_harc_u128, 2>, 2> v{};"),
        (
            "uint<1024>",
            "std::array<std::array<harc_rt::HarcWide<32>, 2>, 2> v{};",
        ),
    ] {
        let src = prog(elem, "v[0][1] = x\n        n = n + v[0][1]");
        let cpp = emit_cpp_src(&src);
        assert!(
            cpp.contains(member),
            "`Vec<Vec<{elem}, 2>, 2>`: tbir must emit `{member}`, got:\n{}",
            cpp.lines()
                .filter(|l| l.contains("array"))
                .collect::<Vec<_>>()
                .join("\n")
        );
        assert!(
            cpp_tb::emit(&merged_src(&src))
                .expect("v1 emits")
                .contains(member),
            "v1 must emit the same member `{member}` for `Vec<Vec<{elem}, 2>, 2>`"
        );
        // The two-level index, read and write.
        assert!(
            cpp.contains("self.v[0][1] = x;"),
            "nested write must emit `self.v[0][1] = x;`:\n{cpp}"
        );
        assert!(
            cpp.contains("self.v[0][1]"),
            "nested read must emit `self.v[0][1]`"
        );
    }

    // A nested read types as its SCALAR leaf, not the inner array, so a
    // width-sensitive expression sees `uint<8>`. (Regression guard for
    // the element-type resolvers descending on `inner_index`.)
    let dump = format!(
        "{}",
        lower_src(&prog("uint<8>", "v[0][1] = x\n        n = n + v[0][1]"))
            .expect("nested read/write lowers")
    );
    assert!(
        dump.contains("self.v[0][1]"),
        "the dump renders the two-level index:\n{dump}"
    );
}

/// The bounds check and the refusals a nested fixed vector inherits.
/// Each refused row names v1's own limit, so none is a false promise.
#[test]
fn a_nested_fixed_vector_refuses_what_v1_cannot_lower() {
    let scope = |field: &str, body: &str| {
        format!(
            r#"scoreboard Sb
    {field}
    n : uint<32> default 0
    hookable put(x: uint<8>)
        {body}
    end put
end scoreboard Sb
testbench Tb
    dut : Top
    sb : Sb
end testbench Tb
impl T for Tb
    run
        wait 1 cycle
    end run
end impl T"#
        )
    };

    // Both index dimensions are bounds-checked (Invalid — a program
    // error under every backend, so it does NOT point at v1).
    for body in ["v[2][0] = x", "v[0][5] = x"] {
        let err = lower_src(&scope("v : Vec<Vec<uint<8>, 2>, 2>", body))
            .expect_err("out-of-range index is Invalid");
        let msg = assert_invalid(&err);
        assert!(msg.contains("out of range"), "{msg}");
    }

    // A record leaf, a `default`, a whole-vec copy, and a three-level
    // index all stay refused — each is out of v1's supported subset or
    // this batch's cut line.
    let refused = [
        (
            "struct B\n    a : uint<8>\nend struct B\n",
            "v : Vec<Vec<B, 2>, 2>",
            "n = n + 1",
        ),
        ("", "v : Vec<Vec<uint<8>, 2>, 2> default {}", "n = n + 1"),
        (
            "",
            "v : Vec<Vec<uint<8>, 2>, 2>\n    w : Vec<Vec<uint<8>, 2>, 2>",
            "v = w",
        ),
        ("", "v : Vec<Vec<Vec<uint<8>, 2>, 2>, 2>", "v[0][1][0] = x"),
    ];
    for (prefix, field, body) in refused {
        let src = format!("{prefix}{}", scope(field, body));
        assert!(
            lower_src(&src).is_err(),
            "`{field}` / `{body}` must be refused, not lowered"
        );
    }
}

/// A DUT port in the INNER subscript of a nested vector read
/// (`sb.v[0][dut.count_out]`) flows through the whole pipeline — it
/// lowers into `ComponentVecElement::inner_index`, verifies, and emits
/// the port read at the inner position. The IR nodes carry a second
/// index, so every traversal that visits `index` (lowering rewrites,
/// the port/probe/use-before-def walkers, placement) also visits
/// `inner_index`; this guards the read/emit end of that, the analysis
/// walkers being verified by the full pass suite over the lowered form.
#[test]
fn a_dut_port_in_a_nested_vector_inner_index_lowers_and_emits() {
    let src = r#"scoreboard Sb
    v : Vec<Vec<uint<8>, 2>, 2>
    n : uint<32> default 0
    hookable put(x: uint<8>)
        n = n + 1
    end put
end scoreboard Sb
testbench Tb
    dut : Top
    sb : Sb
end testbench Tb
impl T for Tb
    run
        wait until sb.v[0][dut.count_out] == 1
    end run
end impl T"#;
    // Lowers with the port inside `inner_index`, and verifies.
    let prog = lower_src(src).expect("nested inner-index port lowers");
    verify::verify_program(&prog).expect("verifies");
    let dump = format!("{prog}");
    assert!(
        dump.contains("sb.v[0][dut.count_out]"),
        "the port sits in the inner index:\n{dump}"
    );
    // Emits the port read at the inner subscript, the same
    // `harc_read` a single-level index port gets.
    let cpp = emit_cpp_src(src);
    assert!(
        cpp.contains("sb.v[0][harc_rt::harc_read(dut->count_out)]"),
        "the inner-index port is read in the emitted C++:\n{}",
        cpp.lines()
            .filter(|l| l.contains("count_out"))
            .collect::<Vec<_>>()
            .join("\n")
    );
}
/// harc#666: a bare enum-variant name declared by more than one enum has
/// no correct index as a VALUE. TB-IR used to fold it first-wins and
/// substitute silently — `let w : WrResp = OKAY` compiling to 0 when
/// `WrResp.OKAY` is 1 — a wrong number with no diagnostic, and (until v1
/// gained its own guard in harc#662) a wrong number both backends agreed
/// on, so the equivalence harness could not see it. It is now a hard
/// `LowerError::Invalid` naming the owning enums.
#[test]
fn ambiguous_enum_variant_as_a_value_is_rejected() {
    let src = r#"enum RdResp { OKAY, SLVERR }
enum WrResp { SLVERR, OKAY }
test T
    let dut : Top
    run
        let w : WrResp = OKAY
        log(info, "${w}")
    end run
end test T"#;
    let err = lower_src(src).expect_err("an ambiguous variant used as a value must be rejected");
    let msg = assert_invalid(&err);
    assert!(
        msg.contains("`OKAY`") && msg.contains("more than one enum"),
        "the message must name the variant and the ambiguity: {msg}"
    );
    // Both owning enums are named so the user can find them.
    assert!(
        msg.contains("RdResp") && msg.contains("WrResp"),
        "the message must name both owning enums: {msg}"
    );
    // HARC has no `Enum.VARIANT` form, so the fix cannot be "qualify it".
    assert!(
        !msg.contains("qualify"),
        "must not suggest a qualified form the language lacks: {msg}"
    );
    assert!(
        !msg.contains("  "),
        "the message must have no doubled internal whitespace: {msg:?}"
    );
}

/// The complement of the rejection: an ambiguous variant used ONLY inside
/// a `keep` still lowers. Constraint position resolves variants through
/// its own path under the documented first-wins rule, so the rejection is
/// confined to value position and does not regress a program whose only
/// use of the name is a constraint. This is also what keeps v1 and TB-IR
/// agreeing on such a program.
#[test]
fn ambiguous_enum_variant_in_a_keep_still_lowers() {
    let src = r#"enum RdResp { OKAY, SLVERR }
enum WrResp { SLVERR, OKAY }
transaction Req
    r : RdResp
    keep r == OKAY
end transaction Req
test T
    let dut : Top
    run
        let t : Req
        randomize(t)
        log(info, "${t.r}")
    end run
end test T"#;
    lower_src(src).expect("an ambiguous variant used only in a keep must still lower");
}

/// An UNAMBIGUOUS variant — declared by exactly one enum — is a value as
/// before. The rejection keys on multiple-declaration, not on the name
/// merely appearing in more than one place.
#[test]
fn an_unambiguous_enum_variant_is_still_a_value() {
    let src = r#"enum RdResp { OKAY, SLVERR }
enum Color { RED, GREEN, BLUE }
test T
    let dut : Top
    run
        let c : Color = BLUE
        log(info, "${c}")
    end run
end test T"#;
    lower_src(src).expect("an unambiguous variant used as a value must still lower");
}

/// harc#666, covergroup path: a bin bound (or coverpoint target) naming an
/// ambiguous variant is the same silent-wrong-index bug as a plain value,
/// in a live sampled comparison — `bins hit = {OKAY}` folded `_v == 0`
/// (RdResp first-wins) while v1 rejected it, a v1/tbir divergence. It is
/// now rejected here too, so the backends agree.
#[test]
fn ambiguous_enum_variant_in_a_covergroup_bin_is_rejected() {
    let src = r#"enum RdResp { OKAY, SLVERR }
enum WrResp { SLVERR, OKAY }
covergroup G @(posedge dut.clk)
    cp : cover dut.count
        bins
            hit = {OKAY}
        end bins
end covergroup G
testbench Tb
    dut : Top
    cov : G
end testbench Tb
impl T for Tb
    run
        wait 3 cycles
    end run
end impl T"#;
    let err =
        lower_src(src).expect_err("an ambiguous variant in a covergroup bin must be rejected");
    let msg = assert_invalid(&err);
    assert!(
        msg.contains("`OKAY`") && msg.contains("more than one enum"),
        "the covergroup diagnostic must name the variant and the ambiguity: {msg}"
    );
    assert!(
        msg.contains("covergroup `G` bin `hit`"),
        "the diagnostic should locate the covergroup and name the BIN (not          mislabel it a point): {msg}"
    );
    // Guards the `\`-continuation whitespace bug: the rendered message must
    // not contain a run of stray internal spaces.
    assert!(
        !msg.contains("  "),
        "the message must have no doubled internal whitespace: {msg:?}"
    );
}

/// The complement: an UNAMBIGUOUS variant in a covergroup bin still
/// lowers. The rejection keys on multiple-declaration, not on a variant
/// appearing in a bin.
#[test]
fn an_unambiguous_enum_variant_in_a_covergroup_bin_still_lowers() {
    let src = r#"enum Color { RED, GREEN, BLUE }
covergroup G @(posedge dut.clk)
    cp : cover dut.count
        bins
            r = {RED}
            g = {GREEN}
        end bins
end covergroup G
testbench Tb
    dut : Top
    cov : G
end testbench Tb
impl T for Tb
    run
        wait 3 cycles
    end run
end impl T"#;
    lower_src(src).expect("an unambiguous variant in a covergroup bin must still lower");
}

/// A `Vec<T, N>` TESTBENCH host field lowers, verifies, emits, and matches
/// v1 byte-for-byte — the member declaration (a zero-filled `std::array`
/// through the shared `field_scalar_cty` seam, so every element class and
/// nesting depth v1 handles is handled here too) and the `_tb.mem[i]`
/// element read/write. v1's own lines are DERIVED, not pasted, so the test
/// pins what the oracle emits rather than what the author recalled.
#[test]
fn a_testbench_fixed_vector_field_matches_v1() {
    let mk = |field: &str, body: &str| {
        format!(
            r#"testbench Tb
    dut : Top
    {field}
end testbench Tb
impl T for Tb
    run
        {body}
        wait 1 cycle
    end run
end impl T"#
        )
    };
    // (field type, member, index shape). All element classes the field
    // seam distinguishes (u64 / int64_t / _harc_u128 / HarcWide<N>), plus
    // a nested `Vec<Vec<..>>`.
    let cases = [
        (
            "mem : Vec<uint<8>, 4>",
            "std::array<uint64_t, 4> mem{};",
            "mem[0] = 5\n        mem[1] = mem[0]",
        ),
        (
            "mem : Vec<sint<8>, 4>",
            "std::array<int64_t, 4> mem{};",
            "mem[0] = 5\n        mem[1] = mem[0]",
        ),
        (
            "mem : Vec<uint<128>, 4>",
            "std::array<_harc_u128, 4> mem{};",
            "mem[0] = 5\n        mem[1] = mem[0]",
        ),
        (
            "mem : Vec<uint<1024>, 4>",
            "std::array<harc_rt::HarcWide<32>, 4> mem{};",
            "mem[0] = 5",
        ),
        (
            "mem : Vec<Vec<uint<8>, 2>, 2>",
            "std::array<std::array<uint64_t, 2>, 2> mem{};",
            "mem[0][1] = 5\n        mem[1][0] = mem[0][1]",
        ),
    ];
    for (field, member, body) in cases {
        let src = mk(field, body);
        let v1 = cpp_tb::emit(&merged_src(&src)).expect("v1 emits");
        let tb = emit_cpp_src(&src);
        // Both emit the same `std::array` member declaration.
        assert!(
            v1.contains(member),
            "v1 must emit member `{member}` for `{field}`"
        );
        assert!(
            tb.contains(member),
            "tbir must emit member `{member}` for `{field}`, got:\n{}",
            tb.lines()
                .filter(|l| l.contains("mem"))
                .collect::<Vec<_>>()
                .join("\n")
        );
        // And the same `_tb.mem[...]` element reads/writes, line-for-line.
        let v1_mem: Vec<&str> = v1
            .lines()
            .map(str::trim)
            .filter(|l| l.contains("_tb.mem"))
            .collect();
        let tb_mem: Vec<&str> = tb
            .lines()
            .map(str::trim)
            .filter(|l| l.contains("_tb.mem"))
            .collect();
        assert!(
            !v1_mem.is_empty(),
            "`{field}`: v1 emits no element access — probe is inert"
        );
        assert_eq!(
            v1_mem, tb_mem,
            "`{field}`: tbir element access must match v1 line-for-line"
        );
    }
}

/// The refusals a testbench fixed-vector field inherits, each graded on
/// MEASURED v1 behaviour. A `default` and a test-scope `let Vec` both make
/// v1 emit C++ that does not compile, so they are `NotImplemented`
/// (EmitsUncompilable), never a `--codegen v1` promise; an out-of-range
/// literal index is a program error (Invalid) under every backend.
#[test]
fn a_testbench_fixed_vector_field_refuses_what_v1_cannot_lower() {
    let mk = |field: &str, body: &str| {
        format!(
            r#"testbench Tb
    dut : Top
    {field}
end testbench Tb
impl T for Tb
    run
        {body}
        wait 1 cycle
    end run
end impl T"#
        )
    };

    // A `default` on the field: v1 emits `std::array<...> mem = <lit>;`,
    // which std::array has no constructor for (measured).
    let err = lower_src(&mk("mem : Vec<uint<8>, 4> default 0", "wait 1 cycle"))
        .expect_err("a default on a fixed-vector field is refused");
    let msg = assert_not_implemented(&err, lower::V1Status::EmitsUncompilable);
    assert!(msg.contains("default"), "{msg}");

    // Out-of-range literal indices — Invalid (a program error, so NOT a
    // `--codegen v1` suggestion), both dimensions of a nested field.
    for body in ["mem[9] = 5", "mem[0][9] = 5"] {
        let err = lower_src(&mk("mem : Vec<Vec<uint<8>, 2>, 2>", body))
            .expect_err("an out-of-range index is Invalid");
        let msg = assert_invalid(&err);
        assert!(msg.contains("out of range"), "{msg}");
    }

    // A test-scope `let m : Vec<T, N>`: v1 declares it as a scalar
    // (`int64_t m = 0;`) and subscripts it — uncompilable (measured). The
    // message must NOT falsely promise `--codegen v1` works.
    let letv = r#"testbench Tb
    dut : Top
end testbench Tb
impl T for Tb
    run
        let m : Vec<uint<8>, 4>
        m[0] = 5
        wait 1 cycle
    end run
end impl T"#;
    let err = lower_src(letv).expect_err("a test-scope let Vec is refused");
    let msg = assert_not_implemented(&err, lower::V1Status::EmitsUncompilable);
    assert!(
        !msg.contains("re-run with `--codegen v1`"),
        "let-Vec message must not promise --codegen v1 works: {msg}"
    );
}

/// A value-returning transactor method call in a fixed-vector
/// testbench-field INDEX. In a STATEMENT context (`dut.en = mem[xt.idx()]`,
/// `let z = mem[xt.idx()]`) the call hoists to a `Stmt::TransactorCall`
/// exactly as the write path does, lowers, verifies, and compiles like v1.
/// In a `wait until` predicate it cannot hoist (the predicate re-evaluates
/// every cycle), so it earns the SAME honest refusal a bare call there
/// does — never a verifier `BadTransactorCall` crash on the un-hoisted
/// edge. Regression guard for the `hoist_transactor_calls` /
/// `expr_has_transactor_edge` walkers, which must both see the new node.
#[test]
fn a_transactor_call_in_a_tb_vec_index_hoists_or_is_refused_like_v1() {
    let mk = |body: &str| {
        format!(
            r#"transactor Xt
    dut : Top
    when active
        hookable idx() -> uint<8>
            return 3
        end idx
    end when
end transactor Xt
testbench Tb
    dut : Top
    xt  : Xt active
    mem : Vec<uint<8>, 4>
end testbench Tb
impl T for Tb
    run
        xt.dut = dut
        {body}
        wait 1 cycle
    end run
end impl T"#
        )
    };

    // Statement contexts: v1 compiles, tbir lowers + verifies (call hoisted).
    for body in ["dut.en = mem[xt.idx()]", "let z : uint<8> = mem[xt.idx()]"] {
        let src = mk(body);
        assert!(
            cpp_tb::emit(&merged_src(&src)).is_ok(),
            "v1 must emit `{body}`"
        );
        let prog = lower_src(&src).unwrap_or_else(|e| panic!("`{body}` must lower: {e}"));
        verify::verify_program(&prog)
            .unwrap_or_else(|e| panic!("`{body}` must verify (call hoisted): {e:?}"));
    }

    // `wait until` predicate: the call cannot hoist. Same honest refusal a
    // bare call earns — an `Unsupported` (v1 does compile the re-eval loop),
    // NOT a verifier crash.
    let err = lower_src(&mk("wait until mem[xt.idx()] == 1"))
        .expect_err("a transactor call in a wait-until predicate is refused");
    let msg = assert_unsupported(&err);
    assert!(
        msg.contains("wait until"),
        "must be the wait-until-predicate refusal, not a verifier crash: {msg}"
    );
}

/// A signed scalar STATE field wider than 64 bits now LOWERS and
/// verifies (harc#657 PR-B), on both owners.
///
/// harc#673 had refused it with an honest `NotImplemented` diagnostic
/// while the operators underneath were still unsigned-by-magnitude; PR-A
/// routed those operators through the two's-complement helpers, so the
/// field cap comes down here. Both owners — a data-only scoreboard field
/// and a method-bearing component field — reach the schema through
/// different call sites (`scoreboards.rs` and `components_impl.rs`) and
/// must agree.
#[test]
fn a_signed_wide_state_field_lowers_now_that_its_operators_are_signed() {
    let scoreboard = r#"scoreboard SignedSb
    v : sint<129> default 0
end scoreboard SignedSb

testbench STb
    dut : Top
    sb  : SignedSb
end testbench STb

impl STest for STb
    run
        wait 1 cycle
    end run
end impl STest
"#;
    let component = r#"scoreboard SignedComp
    v : sint<129> default 0

    hookable refresh()
        v = v
    end refresh
end scoreboard SignedComp

testbench CTb
    dut : Top
    c   : SignedComp
end testbench CTb

impl CTest for CTb
    run
        wait 1 cycle
    end run
end impl CTest
"#;
    for (owner, src) in [("scoreboard", scoreboard), ("component", component)] {
        // The deliverable: it lowers AND verifies. Before PR-B the
        // lowering gate (both owners) and the verifier (the data-only
        // scoreboard path) capped signed at 64, so one or the other
        // refused a `sint<129>` field — the second as an internal error
        // for source lowering had accepted.
        let prog = lower_src(src)
            .unwrap_or_else(|e| panic!("{owner}: a signed wide field must lower now: {e:?}"));
        verify::verify_program(&prog)
            .unwrap_or_else(|e| panic!("{owner}: a signed wide field must verify: {e:?}"));
    }

    // Width boundaries still hold: `sint` past the 1024-bit ceiling is
    // still refused, same as unsigned.
    let too_wide = "scoreboard Ov
    v : sint<1025> default 0
end scoreboard Ov

         testbench T
    dut : Top
    sb : Ov
end testbench T

         impl I for T
    run
        wait 1 cycle
    end run
end impl I
";
    assert!(
        lower_src(too_wide).is_err(),
        "a signed field past the 1024-bit ceiling must still be refused"
    );
}

/// A no-payload `on <event>()` handler lowers exactly as the one-argument
/// form does — same subscriber-list member and fan-out as v1 — on every
/// host that can reach it (agent / env / transactor). v1 synthesizes a
/// throwaway parameter; tbir binds the payload to a synthesized `_v` the
/// body never reads, so the emitted handler is trace-equivalent. Only the
/// binding name differs, and names do not affect runtime behaviour.
#[test]
fn a_no_arg_event_handler_lowers_like_the_one_arg_form() {
    let mk = |kind: &str, arg: &str| {
        format!(
            r#"{kind} Tagger
    in_ev : event<uint<8>>
    seen  : uint<32> default 0
    on in_ev({arg})
        seen = seen + 1
    end on
end {kind} Tagger
testbench Tb
    dut : Top
    tagger : Tagger{mode}
end testbench Tb
impl T for Tb
    run
        emit tagger.in_ev(1)
        wait 1 cycle
    end run
end impl T"#,
            // A transactor instance field must carry a mode; a passive
            // instance still exposes its always-on `on` handler. `agent` /
            // `env` fields take no mode.
            mode = if kind == "transactor" { " passive" } else { "" }
        )
    };
    for kind in ["agent", "env", "transactor"] {
        let src = mk(kind, "");
        // v1 accepts it; derive the subscriber-list member from v1 rather
        // than pasting it.
        let v1 = cpp_tb::emit(&merged_src(&src)).expect("v1 emits the no-arg handler");
        let member = "std::vector<std::function<void(uint64_t)>> in_ev;";
        assert!(v1.contains(member), "[{kind}] v1 must emit `{member}`");

        // tbir lowers, verifies, and emits the same subscriber-list member
        // plus the handler dispatch — identical to the one-arg form.
        let prog =
            lower_src(&src).unwrap_or_else(|e| panic!("[{kind}] no-arg handler lowers: {e}"));
        verify::verify_program(&prog).unwrap_or_else(|e| panic!("[{kind}] verifies: {e:?}"));
        let tb = tbir::emit(&prog, &merged_src(&src), &cpp_tb::EmitOpts::default())
            .unwrap_or_else(|e| panic!("[{kind}] emits: {e}"));
        assert!(tb.contains(member), "[{kind}] tbir must emit `{member}`");
        assert!(
            tb.contains("tagger.in_ev.push_back(") && tb.contains("for (auto& _s : tagger.in_ev)"),
            "[{kind}] tbir must emit the subscriber push + fan-out"
        );

        // The one-arg form still lowers (no regression), and its member is
        // byte-identical to the no-arg form's.
        let one =
            lower_src(&mk(kind, "t")).unwrap_or_else(|e| panic!("[{kind}] one-arg lowers: {e}"));
        let one_cpp = tbir::emit(
            &one,
            &merged_src(&mk(kind, "t")),
            &cpp_tb::EmitOpts::default(),
        )
        .expect("one-arg emits");
        assert!(one_cpp.contains(member), "[{kind}] one-arg member matches");
    }
}

/// A `default` on a record-typed component field is refused honestly, not
/// pointed at `--codegen v1`: v1 emits `<Record> r = <lit>;` and g++
/// rejects the int-to-record conversion (measured). The DUT-handle sibling
/// (`dut : Top default 0`) keeps its `--codegen v1` suggestion — v1 does
/// compile `VTop* dut = 0;` — so this regrade is the record site alone.
#[test]
fn a_default_on_a_record_component_field_is_refused_without_a_false_v1_promise() {
    let src = r#"struct Beat
    p : uint<8>
end struct Beat
agent Ag
    r : Beat default 0
    seen : uint<32> default 0
end agent Ag
testbench Tb2
    dut : Top
    ag : Ag
end testbench Tb2
impl T2 for Tb2
    run
        wait 1 cycle
    end run
end impl T2"#;
    let err = lower_src(src).expect_err("a default on a record component field is refused");
    let msg = assert_not_implemented(&err, lower::V1Status::EmitsUncompilable);
    assert!(
        !msg.contains("re-run with `--codegen v1`"),
        "record-default message must not promise v1 works: {msg}"
    );
}

/// Adversarial-review regressions for the no-payload `on <event>()` batch:
/// (1) a component FIELD named `_v` must NOT be shadowed by the synthesized
/// throwaway payload param — the body's `_v` must read the field, as under
/// v1 (which qualifies every field read); (2) a TEST-SCOPE no-arg
/// subscription (`on e()` on an `event` local) lowers, matching v1, rather
/// than being falsely refused as `Invalid`.
#[test]
fn the_no_arg_handler_payload_never_shadows_a_field() {
    let coll = r#"agent Ag
    ev : event<uint<8>>
    _v : uint<8> default 7
    seen : uint<32> default 0
    on ev()
        seen = seen + _v
    end on
end agent Ag
testbench Tb
    dut : Top
    ag : Ag
end testbench Tb
impl T for Tb
    run
        emit ag.ev(1)
        wait 1 cycle
    end run
end impl T"#;
    // v1 reads the field (`_tb.ag._v`); tbir must read the field too
    // (`self._v`), NOT a bare payload param `_v`.
    let tb = emit_cpp_src(coll);
    assert!(
        tb.contains("self._v"),
        "the body's `_v` must resolve to the field (self._v), not the payload param:\n{}",
        tb.lines()
            .filter(|l| l.contains("seen") && l.contains("_v"))
            .collect::<Vec<_>>()
            .join("\n")
    );
    assert!(
        !tb.lines()
            .any(|l| l.contains("seen") && l.contains("+ _v)") && !l.contains("self._v")),
        "the payload param must not shadow the field"
    );
    // And v1 agrees the field is what's read.
    assert!(
        cpp_tb::emit(&merged_src(coll))
            .expect("v1")
            .contains("_tb.ag._v"),
        "v1 reads the field for `_v`"
    );
}

/// A test-scope `on <ev>()` subscription with no payload binding lowers and
/// verifies (v1 compiles it), rather than the false `Invalid` grade the
/// arity arm gave before — the test-scope sibling of the component-path
/// no-arg handler.
#[test]
fn a_test_scope_no_arg_event_subscription_lowers_like_v1() {
    let src = r#"testbench Tb
    dut : Top
end testbench Tb
impl T for Tb
    run
        let e : event<uint<8>>
        on e()
            log(info, "fired")
        end on
        emit e(3)
        wait 1 cycle
    end run
end impl T"#;
    assert!(
        cpp_tb::emit(&merged_src(src)).is_ok(),
        "v1 compiles a test-scope no-arg subscription"
    );
    let prog = lower_src(src).expect("test-scope no-arg subscription lowers");
    verify::verify_program(&prog).expect("verifies");
    tbir::emit(&prog, &merged_src(src), &cpp_tb::EmitOpts::default()).expect("emits");
}

/// A bare read or write of a `queue` state field in a bound-to target
/// responder body is refused honestly, not pointed at `--codegen v1`: v1
/// emits the bare op against the `harc_rt::HarcQueue<...>` member and g++
/// rejects it (`no match for operator=` on a write; `cannot convert
/// HarcQueue to uint64_t` on a read — measured). Mutate/read via the queue
/// ops. The valid `.push(x)` control lowers under both backends.
#[test]
fn a_bare_queue_state_field_op_is_refused_without_a_false_v1_promise() {
    let mk = |body: &str| {
        format!(
            r#"bus TlmMemBus
    tlm_method read(addr: uint<8>) -> uint<32>: blocking;
end bus TlmMemBus
transactor TlmMemTarget bound to TlmMemBus
    n : uint<32> default 0
    q : queue<uint<8>>
    thread bus.read(addr: uint<8>)
        {body}
        return 1
    end thread
end transactor TlmMemTarget
testbench Tb
    dut : TlmReadInitiator
end testbench Tb
impl T for Tb
    let mem : TlmMemBus = bind dut
    let target : TlmMemTarget passive = bind mem
    run
        dut.rst = 1
        wait 2 cycles
    end run
end impl T"#
        )
    };
    for (op, what) in [("q = 1", "bare assignment"), ("n = q", "bare read")] {
        let err = lower_src(&mk(op))
            .err()
            .unwrap_or_else(|| panic!("`{op}` must be refused"));
        let msg = assert_not_implemented(&err, lower::V1Status::EmitsUncompilable);
        assert!(
            !msg.contains("re-run with `--codegen v1`"),
            "{what}: must not promise v1 works: {msg}"
        );
    }
    // Control: the queue field itself is fine — a valid op lowers.
    lower_src(&mk("q.push(1)")).expect("a valid queue op lowers");
}

/// A target thread that does not name `bus.<method>` is a program error
/// (`Invalid`), not a `--codegen v1` suggestion: v1 refuses it too. Guards
/// the regrade of the `thread <x>`-shape arm to match its sibling arms.
#[test]
fn a_non_bus_target_thread_is_invalid_not_a_v1_suggestion() {
    let src = r#"bus TlmMemBus
    tlm_method read(addr: uint<8>) -> uint<32>: blocking;
end bus TlmMemBus
transactor TlmMemTarget bound to TlmMemBus
    n : uint<32> default 0
    thread run_loop(addr: uint<8>)
        n = n + 1
        return 1
    end thread
end transactor TlmMemTarget
testbench Tb
    dut : TlmReadInitiator
end testbench Tb
impl T for Tb
    let mem : TlmMemBus = bind dut
    let target : TlmMemTarget passive = bind mem
    run
        dut.rst = 1
        wait 2 cycles
    end run
end impl T"#;
    let err = lower_src(src).expect_err("a non-`bus.<method>` target thread is refused");
    let msg = assert_invalid(&err);
    assert!(
        msg.contains("bus.<method>"),
        "must name the required `bus.<method>` shape: {msg}"
    );
}

/// A record-element fixed-vector component field (`v : Vec<Beat, 2>`, or a
/// nested `Vec<Vec<Beat, 2>, 2>`) is refused honestly, not pointed at
/// `--codegen v1`: v1 does not recognize a record-element `Vec` field and
/// falls back to a scalar `uint64_t` member, so any element access
/// subscripts the scalar and g++ refuses (`invalid types 'uint64_t[int]'
/// for array subscript` — measured uniform on scoreboard / agent / env).
/// Scalar-element fixed vectors are unaffected (they lower).
#[test]
fn a_record_element_fixed_vector_field_is_refused_without_a_false_v1_promise() {
    let mk = |kind: &str, elem: &str| {
        format!(
            r#"struct Beat
    p : uint<8>
end struct Beat
{kind} Sb
    v : Vec<{elem}, 2>
    n : uint<32> default 0
    hookable put(x: uint<8>)
        n = n + 1
    end put
end {kind} Sb
testbench Tb
    dut : Top
    sb : Sb
end testbench Tb
impl T for Tb
    run
        wait 1 cycle
    end run
end impl T"#
        )
    };
    for kind in ["scoreboard", "agent", "env"] {
        for elem in ["Beat", "Vec<Beat, 2>"] {
            let err = lower_src(&mk(kind, elem))
                .err()
                .unwrap_or_else(|| panic!("[{kind}] `Vec<{elem}, 2>` must be refused"));
            let msg = assert_not_implemented(&err, lower::V1Status::EmitsUncompilable);
            assert!(
                !msg.contains("re-run with `--codegen v1`"),
                "[{kind}/{elem}] must not promise v1 works: {msg}"
            );
        }
        // No regression: a scalar-element fixed vector still lowers.
        lower_src(&mk(kind, "uint<8>"))
            .unwrap_or_else(|e| panic!("[{kind}] scalar Vec lowers: {e}"));
    }
}

/// A wrapping operator (`+%`/`-%`/`*%`) at operand width > 64 is refused
/// honestly, not pointed at `--codegen v1`: v1 has its own identical gate
/// and refuses it too (`Rejects` — v1 emits no C++). A wrapping op at 64
/// bits still lowers.
#[test]
fn a_wide_wrapping_operator_is_refused_without_a_false_v1_promise() {
    let mk = |op: &str, w: u32| {
        format!(
            r#"testbench Tb
    dut : Top
end testbench Tb
impl T for Tb
    run
        let a : uint<{w}> = 7
        let r : uint<{w}> = a {op} a
        wait 1 cycle
    end run
end impl T"#
        )
    };
    for op in ["+%", "-%", "*%"] {
        let err = lower_src(&mk(op, 128))
            .err()
            .unwrap_or_else(|| panic!("`{op}` at 128 must be refused"));
        assert_not_implemented(&err, lower::V1Status::Rejects);
        // No regression: the same operator at 64 bits lowers.
        lower_src(&mk(op, 64)).unwrap_or_else(|e| panic!("`{op}` at 64 lowers: {e}"));
    }
}

/// The directional narrowing check on a ≤64-bit component scalar field,
/// with the manufactured-width carve-out (harc#658).
///
/// harc#656 added this check but bounded it to destinations past 64
/// bits, because a widthless operand (an `on ev(t)` payload param, a
/// file-scope `const`) makes `common_expr_type` manufacture a 64-bit
/// result width, which flagged the ordinary counting idiom
/// `seen = seen + t` as a narrowing into a ≤64-bit field. The bound is
/// gone now: payload params carry their declared width, and the check
/// skips a width MANUFACTURED from any remaining widthless leaf. So the
/// verdict rests only on declared widths, at every field width.
#[test]
fn a_le64_component_field_write_is_checked_without_manufactured_widths() {
    let src = |fields: &str, body: &str| {
        format!(
            "domain SysDomain\n  freq_mhz: 100\nend domain SysDomain\n\
             const N = 9\n\
             agent A\n    in_ev : event<uint<8>>\n{fields}\n    \
             on in_ev(t)\n        {body}\n    end on\n\
             end agent A\n\n\
             test T\n    let dut : Top\n    let a : A\n    clock clk = SysDomain\n    \
             run\n        wait 2 cycles\n        emit a.in_ev(1)\n        wait 2 cycles\n    end run\n\
             end test T\n"
        )
    };

    // Lowers: a payload param carries its declared width, so
    // `seen(uint<32>) + t(uint<8>)` is 32-bit — no narrowing.
    lower_src(&src("    seen : uint<32> default 0", "seen = seen + t"))
        .expect("`seen = seen + t` on a payload param must lower");

    // Lowers: a widthless `const` manufactures a 64-bit width, which the
    // check must NOT treat as a real narrowing.
    lower_src(&src("    seen : uint<32> default 0", "seen = seen + N"))
        .expect("`seen = seen + N` for a widthless const must lower");

    // Refuses: a DECLARED wider width into a narrower ≤64-bit field is a
    // genuine narrowing. This is the case the >64 bound used to let
    // through — TB-IR stricter than v1, which truncates it silently.
    let err = lower_src(&src(
        "    seen : uint<32> default 0\n    wide : uint<48> default 0",
        "seen = wide",
    ))
    .expect_err("a uint<48> value into a uint<32> field must be refused");
    let msg = err.to_string();
    assert!(
        matches!(err, lower::LowerError::Invalid(_))
            && msg.contains("48-bit value")
            && msg.contains("component field `seen`, declared 32 bits")
            && msg.contains("narrows"),
        "the ≤64 narrowing diagnostic must name both widths: {msg}"
    );

    // Refuses: an implicit signedness change on a ≤64 field, unaffected
    // by the manufactured-width carve-out (signedness is always known).
    let err = lower_src(&src(
        "    u : uint<32> default 0\n    sv : sint<16> default 0",
        "u = sv",
    ))
    .expect_err("a signed value into an unsigned ≤64 field must be refused");
    assert!(
        err.to_string().contains("Signedness must match"),
        "signedness mismatch must still be caught at ≤64: {err}"
    );
}
